mapper.select:


    appMenu.deleted_flag = 'N' and  menu.deleted_flag = 'N'
    and appMenu.app_id = #{appId}
    and appMenu.menu_id = #{menuId}
    and appMenu.status = #{status}
    and appMenu.remark like concat('%', #{remark}, '%')
    and menu.menu_name like concat('%', #{menuName}, '%')
    and appMenu.organization_id =
        #{organizationId}


        and

            (
            appMenu.remark like concat('%', #{item}, '%')
            or
            menu.menu_name like concat('%', #{item}, '%')
            )



order by appMenu.created_time desc

select distinct

    appMenu.id, menu.remark, menu.menu_name,menu.id as menu_id,appMenu.must_menu,appMenu.visible_menu,menu.permission as permission,
    menu.menu_type,  menu.status, menu.organization_id, menu.parent_id,menu.order_num

from system_app_menu as appMenu
left join system_menu as menu on appMenu.menu_id = menu.id


    menu.visible=1 and  appMenu.deleted_flag='N'  and menu.deleted_flag = 'N' and menu.app_menu=0
    and appMenu.app_id = #{appId}
    and appMenu.menu_id = #{menuId}
    and appMenu.must_menu = #{mustMenu}
    and appMenu.visible_menu = #{visibleMenu}
    and appMenu.status = #{status}
    and appMenu.remark like concat('%', #{remark}, '%')
    and menu.menu_name like concat('%', #{menuName}, '%')
    and appMenu.organization_id =
        #{organizationId}


        and

            (
            appMenu.remark like concat('%', #{item}, '%')
            or
            menu.menu_name like concat('%', #{item}, '%')
            )



order by menu.parent_id, menu.order_num desc
